// 다중 선택 항목 일괄 편집 모달
import React, { useState, useMemo } from 'react';
import type { Project, ProjectTask, ProjectTodo } from '../../types/work';
import { useDraggable } from '../../hooks/useDraggable';
import './BulkEditModal.css';

type ItemType = 'projects' | 'tasks' | 'todos';

interface BulkEditModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedIds: Set<string>;
  itemType: ItemType;
  // 데이터
  projects: Project[];
  tasks: ProjectTask[];
  todos: ProjectTodo[];
  // 액션
  onBulkUpdateProjects?: (ids: string[], updates: Partial<Project>) => Promise<void>;
  onBulkUpdateTasks?: (ids: string[], updates: Partial<ProjectTask>) => Promise<void>;
  onBulkUpdateTodos?: (ids: string[], updates: Partial<ProjectTodo>) => Promise<void>;
  onBulkDeleteProjects?: (ids: string[]) => Promise<void>;
  onBulkDeleteTasks?: (ids: string[]) => Promise<void>;
  onBulkDeleteTodos?: (ids: string[]) => Promise<void>;
}

export default function BulkEditModal({
  isOpen,
  onClose,
  selectedIds,
  itemType,
  projects,
  tasks,
  todos: _todos,
  onBulkUpdateProjects,
  onBulkUpdateTasks,
  onBulkUpdateTodos,
  onBulkDeleteProjects,
  onBulkDeleteTasks,
  onBulkDeleteTodos,
}: BulkEditModalProps) {
  void _todos; // suppress unused variable warning
  const { position, handleMouseDown, isDragging } = useDraggable('bulk-edit-modal');
  
  // 편집 상태
  const [changeProject, setChangeProject] = useState(false);
  const [newProjectId, setNewProjectId] = useState<string>('');
  const [changeTask, setChangeTask] = useState(false);
  const [newTaskId, setNewTaskId] = useState<string>('');
  const [changeDueDate, setChangeDueDate] = useState(false);
  const [newDueDate, setNewDueDate] = useState<string>('');
  const [changeEndDate, setChangeEndDate] = useState(false);
  const [newEndDate, setNewEndDate] = useState<string>('');
  const [isSaving, setIsSaving] = useState(false);

  // 선택된 항목 수
  const selectedCount = selectedIds.size;

  // 타입에 따른 라벨
  const typeLabel = useMemo(() => {
    switch (itemType) {
      case 'projects': return 'Project';
      case 'tasks': return 'Task';
      case 'todos': return 'To do';
      default: return '항목';
    }
  }, [itemType]);

  // 프로젝트 옵션 (tasks, todos용)
  const projectOptions = useMemo(() => {
    return projects.filter(p => p.status === 'ACTIVE');
  }, [projects]);

  // 태스크 옵션 (todos용, 선택된 프로젝트에 따라 필터링)
  const taskOptions = useMemo(() => {
    if (newProjectId) {
      return tasks.filter(t => t.projectId === newProjectId && t.status === 'ACTIVE');
    }
    return tasks.filter(t => t.status === 'ACTIVE');
  }, [tasks, newProjectId]);

  if (!isOpen) return null;

  const handleSave = async () => {
    if (selectedCount === 0) return;
    
    setIsSaving(true);
    try {
      const ids = Array.from(selectedIds);

      if (itemType === 'projects' && onBulkUpdateProjects) {
        const updates: Partial<Project> = {};
        if (changeDueDate) updates.due_at = newDueDate || null;
        if (changeEndDate) updates.end_at = newEndDate || null;
        if (Object.keys(updates).length > 0) {
          await onBulkUpdateProjects(ids, updates);
        }
      } else if (itemType === 'tasks' && onBulkUpdateTasks) {
        const updates: Partial<ProjectTask> = {};
        if (changeProject && newProjectId) updates.projectId = newProjectId;
        if (changeDueDate) updates.due_at = newDueDate || null;
        if (changeEndDate) updates.end_at = newEndDate || null;
        if (Object.keys(updates).length > 0) {
          await onBulkUpdateTasks(ids, updates);
        }
      } else if (itemType === 'todos' && onBulkUpdateTodos) {
        const updates: Partial<ProjectTodo> = {};
        if (changeTask && newTaskId) updates.taskId = newTaskId;
        if (changeDueDate) updates.due_at = newDueDate || null;
        if (changeEndDate) updates.end_at = newEndDate || null;
        if (Object.keys(updates).length > 0) {
          await onBulkUpdateTodos(ids, updates);
        }
      }
      
      onClose();
    } catch (error) {
      console.error('Failed to bulk update:', error);
      alert('일괄 수정에 실패했습니다.');
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async () => {
    if (selectedCount === 0) return;
    
    const confirmMsg = `선택된 ${selectedCount}개의 ${typeLabel}을(를) 삭제하시겠습니까?\n이 작업은 되돌릴 수 없습니다.`;
    if (!confirm(confirmMsg)) return;

    setIsSaving(true);
    try {
      const ids = Array.from(selectedIds);

      if (itemType === 'projects' && onBulkDeleteProjects) {
        await onBulkDeleteProjects(ids);
      } else if (itemType === 'tasks' && onBulkDeleteTasks) {
        await onBulkDeleteTasks(ids);
      } else if (itemType === 'todos' && onBulkDeleteTodos) {
        await onBulkDeleteTodos(ids);
      }
      
      onClose();
    } catch (error) {
      console.error('Failed to bulk delete:', error);
      alert('일괄 삭제에 실패했습니다.');
    } finally {
      setIsSaving(false);
    }
  };

  const handleOverlayClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  return (
    <div className="bulk-edit-modal-overlay" onClick={handleOverlayClick}>
      <div 
        className={`bulk-edit-modal ${isDragging ? 'dragging' : ''}`}
        style={{ 
          transform: position ? `translate(${position.x}px, ${position.y}px)` : undefined,
        }}
      >
        <div 
          className="modal-header"
          onMouseDown={handleMouseDown}
        >
          <h2>일괄 편집 ({selectedCount}개 선택됨)</h2>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>

        <div className="modal-body">
          <p className="selection-info">
            {selectedCount}개의 {typeLabel}이(가) 선택되었습니다.
          </p>

          {/* 소속 변경 - Tasks */}
          {itemType === 'tasks' && (
            <div className="bulk-edit-option">
              <label className="option-checkbox">
                <input
                  type="checkbox"
                  checked={changeProject}
                  onChange={(e) => setChangeProject(e.target.checked)}
                />
                <span>소속 Project 변경</span>
              </label>
              {changeProject && (
                <select
                  value={newProjectId}
                  onChange={(e) => setNewProjectId(e.target.value)}
                  className="option-select"
                >
                  <option value="">프로젝트 선택...</option>
                  {projectOptions.map(p => (
                    <option key={p.id} value={p.id}>{p.title}</option>
                  ))}
                </select>
              )}
            </div>
          )}

          {/* 소속 변경 - Todos */}
          {itemType === 'todos' && (
            <div className="bulk-edit-option">
              <label className="option-checkbox">
                <input
                  type="checkbox"
                  checked={changeTask}
                  onChange={(e) => setChangeTask(e.target.checked)}
                />
                <span>소속 Task 변경</span>
              </label>
              {changeTask && (
                <>
                  <select
                    value={newProjectId}
                    onChange={(e) => {
                      setNewProjectId(e.target.value);
                      setNewTaskId('');
                    }}
                    className="option-select"
                  >
                    <option value="">프로젝트 선택...</option>
                    {projectOptions.map(p => (
                      <option key={p.id} value={p.id}>{p.title}</option>
                    ))}
                  </select>
                  <select
                    value={newTaskId}
                    onChange={(e) => setNewTaskId(e.target.value)}
                    className="option-select"
                    disabled={!newProjectId}
                  >
                    <option value="">Task 선택...</option>
                    {taskOptions.map(t => (
                      <option key={t.id} value={t.id}>{t.title}</option>
                    ))}
                  </select>
                </>
              )}
            </div>
          )}

          {/* 마감일 변경 */}
          <div className="bulk-edit-option">
            <label className="option-checkbox">
              <input
                type="checkbox"
                checked={changeDueDate}
                onChange={(e) => setChangeDueDate(e.target.checked)}
              />
              <span>마감일 변경</span>
            </label>
            {changeDueDate && (
              <input
                type="date"
                value={newDueDate}
                onChange={(e) => setNewDueDate(e.target.value)}
                className="option-input"
              />
            )}
          </div>

          {/* 종료일 변경 */}
          <div className="bulk-edit-option">
            <label className="option-checkbox">
              <input
                type="checkbox"
                checked={changeEndDate}
                onChange={(e) => setChangeEndDate(e.target.checked)}
              />
              <span>종료일 변경</span>
            </label>
            {changeEndDate && (
              <input
                type="date"
                value={newEndDate}
                onChange={(e) => setNewEndDate(e.target.value)}
                className="option-input"
              />
            )}
          </div>
        </div>

        <div className="modal-footer">
          <button 
            className="delete-btn" 
            onClick={handleDelete}
            disabled={isSaving}
          >
            🗑️ 선택 항목 삭제
          </button>
          <div className="footer-right">
            <button className="cancel-btn" onClick={onClose} disabled={isSaving}>
              취소
            </button>
            <button 
              className="save-btn" 
              onClick={handleSave}
              disabled={isSaving || (!changeProject && !changeTask && !changeDueDate && !changeEndDate)}
            >
              {isSaving ? '저장 중...' : '적용'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
